add_action( 'woocommerce_before_shop_loop', 'perfectpixel_category_dropdown_filter', 25 );

function perfectpixel_category_dropdown_filter() {
	if ( ! function_exists( 'wc_product_dropdown_categories' ) ) {
		return;
	}
	echo '<div class="perfectpixel-category-filter" style="margin-bottom:1em">';
	wc_product_dropdown_categories(
		array(
			'show_count'       => 1,
			'hierarchical'     => 1,
			'show_option_none' => '{{category_dropdown_placeholder}}',
			'option_none_value'=> '',
			'value_field'      => 'slug',
			'selected'         => is_product_category() ? get_queried_object()->slug : '',
		)
	);
	echo '</div>';
	$base = wp_json_encode( home_url( '/?product_cat=' ) );
	?>
	<script>
	( function () {
		var select = document.querySelector( '.perfectpixel-category-filter select' );
		if ( select ) {
			select.addEventListener( 'change', function () {
				if ( select.value ) {
					window.location.href = <?php echo $base; ?> + encodeURIComponent( select.value );
				}
			} );
		}
	} )();
	</script>
	<?php
}
